SELECT CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, CASE WHEN unit_price >= 370 THEN 'high' WHEN unit_price >= 160 THEN 'mid' ELSE 'low' END AS unit_price_bucket, MAX(quantity) - MIN(quantity) AS quantity_range FROM order_items WHERE quantity BETWEEN 4 AND 6 GROUP BY CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END, CASE WHEN unit_price >= 370 THEN 'high' WHEN unit_price >= 160 THEN 'mid' ELSE 'low' END HAVING MAX(quantity) - MIN(quantity) > 66 ORDER BY 2 DESC
